CREATE TABLE IF NOT EXISTS pitlane.platform_operators(user_id uuid PRIMARY KEY,active boolean NOT NULL DEFAULT true);
CREATE OR REPLACE FUNCTION pitlane.is_operator(u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT EXISTS(SELECT FROM pitlane.platform_operators WHERE user_id=u AND active) $$;
ALTER TABLE pitlane.orders ADD COLUMN IF NOT EXISTS checkout_id text UNIQUE;
ALTER TABLE pitlane.orders ADD COLUMN IF NOT EXISTS checkout_url text;
ALTER TABLE pitlane.entitlement_lots ADD COLUMN IF NOT EXISTS scope_hashes text[];
CREATE OR REPLACE FUNCTION pitlane.create_order(qid uuid,k text,kind text DEFAULT 'unit',initial_count integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$
DECLARE q pitlane.quotes;o pitlane.orders;j pitlane.jobs;prior pitlane.idempotency;cap bigint=1000000;mode text;
BEGIN SELECT * INTO q FROM pitlane.quotes WHERE id=qid;IF NOT FOUND OR NOT pitlane.can_billing(q.tenant_id) OR NOT pitlane.can_project(q.tenant_id,q.project_id,true) THEN RAISE EXCEPTION 'NOT_FOUND';END IF;
IF k IS NULL OR length(k)<16 OR length(k)>128 OR kind NOT IN('unit','pilot') OR initial_count<1 OR initial_count>5 OR kind='unit' AND initial_count<>1 THEN RAISE EXCEPTION 'INVALID_INPUT';END IF;
SELECT billing_mode INTO mode FROM pitlane.runtime;IF mode='disabled' OR mode IS NULL THEN RAISE EXCEPTION 'BILLING_DISABLED';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(q.tenant_id::text||q.project_id::text,0));SELECT * INTO prior FROM pitlane.idempotency WHERE tenant_id=q.tenant_id AND project_id=q.project_id AND key=k;
IF FOUND THEN IF prior.request_hash<>q.inputs_hash||'/order/'||kind||'/'||initial_count THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;SELECT orders.* INTO o FROM pitlane.orders JOIN pitlane.jobs ON jobs.order_id=orders.id WHERE jobs.id=prior.job_id;RETURN to_jsonb(o);END IF;
SELECT * INTO q FROM pitlane.quotes WHERE id=qid FOR UPDATE;IF q.expires_at<=now() THEN RAISE EXCEPTION 'QUOTE_EXPIRED';END IF;IF q.consumed_job_id IS NOT NULL THEN RAISE EXCEPTION 'QUOTE_CONSUMED';END IF;
PERFORM 1 FROM pitlane.budgets WHERE key IN('environment',q.tenant_id::text) ORDER BY key FOR UPDATE;IF (SELECT count(*) FROM pitlane.budgets WHERE key IN('environment',q.tenant_id::text))<>2 OR EXISTS(SELECT FROM pitlane.budgets WHERE key IN('environment',q.tenant_id::text) AND maximum-reserved-spent<cap) THEN RAISE EXCEPTION 'COST_BUDGET_EXHAUSTED';END IF;
IF (SELECT count(*) FROM pitlane.jobs WHERE tenant_id=q.tenant_id AND project_id=q.project_id AND state IN('queued','running','verifying','retry_wait','awaiting_payment'))>=2 THEN RAISE EXCEPTION 'ACTIVE_LIMIT';END IF;
UPDATE pitlane.budgets SET reserved=reserved+cap WHERE key IN('environment',q.tenant_id::text);
INSERT INTO pitlane.orders(tenant_id,project_id,quote_id,kind,state,amount_cents,initial_units) VALUES(q.tenant_id,q.project_id,q.id,kind,'awaiting_authorization',CASE WHEN kind='pilot' THEN 19900 ELSE q.price_cents END,initial_count) RETURNING * INTO o;
SELECT runtime.mode INTO mode FROM pitlane.runtime;
INSERT INTO pitlane.jobs(tenant_id,project_id,quote_id,input,canonical_key,state,origin,order_id,deadline) VALUES(q.tenant_id,q.project_id,q.id,q.input,'order/'||o.id::text,'awaiting_payment',CASE WHEN mode='local' THEN 'fixture' ELSE 'customer' END,o.id,o.hold_until) RETURNING * INTO j;
UPDATE pitlane.quotes SET consumed_job_id=j.id WHERE id=qid;INSERT INTO pitlane.idempotency VALUES(q.tenant_id,q.project_id,k,q.inputs_hash||'/order/'||kind||'/'||initial_count,j.id,now());
INSERT INTO pitlane.payment_outbox(tenant_id,order_id,business_key,operation) VALUES(o.tenant_id,o.id,o.id::text||'/authorize','authorize');PERFORM pitlane.emit(j.id,'awaiting_payment');RETURN to_jsonb(o);
END $$;
CREATE OR REPLACE FUNCTION pitlane.billing_outbox(maximum integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE result jsonb;BEGIN WITH claimed AS (SELECT id FROM pitlane.payment_outbox WHERE completed_at IS NULL AND available_at<=now() AND (lease_until IS NULL OR lease_until<=now()) AND attempts<10 ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT least(maximum,100)),updated AS (UPDATE pitlane.payment_outbox SET lease_until=now()+interval '30 seconds',attempts=attempts+1 WHERE id IN(SELECT id FROM claimed) RETURNING *) SELECT coalesce(jsonb_agg(updated),'[]') INTO result FROM updated;RETURN result;END $$;
CREATE OR REPLACE FUNCTION pitlane.billing_order(target_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT to_jsonb(o) FROM pitlane.orders o WHERE o.id=target_id $$;
CREATE OR REPLACE FUNCTION pitlane.checkout_created(target_id uuid,checkout text,url text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.orders SET checkout_id=checkout,checkout_url=url WHERE orders.id=target_id AND state='awaiting_authorization' $$;
CREATE OR REPLACE FUNCTION pitlane.order_authorized(target_id uuid,provider text,expiry timestamptz,amount bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE o pitlane.orders;j pitlane.jobs;BEGIN SELECT * INTO o FROM pitlane.orders WHERE orders.id=target_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND';END IF;IF amount<>o.amount_cents OR expiry<=now()+interval '180 seconds' THEN RAISE EXCEPTION 'INVALID_AUTHORIZATION';END IF;IF o.state IN('authorized','delivered_pending_capture','settled') THEN RETURN;END IF;UPDATE pitlane.orders SET provider_id=provider,capture_before=expiry WHERE orders.id=target_id;
IF o.hold_until<=now() OR o.state='cancelled' THEN INSERT INTO pitlane.payment_outbox(tenant_id,order_id,business_key,operation) VALUES(o.tenant_id,target_id,target_id::text||'/cancel','cancel') ON CONFLICT DO NOTHING;RETURN;END IF;
UPDATE pitlane.orders SET state='authorized' WHERE orders.id=target_id;FOR j IN SELECT * FROM pitlane.jobs WHERE order_id=target_id AND state='awaiting_payment' LOOP UPDATE pitlane.jobs SET state='queued',deadline=clock_timestamp()+interval '180 seconds' WHERE jobs.id=j.id;PERFORM pitlane.emit(j.id,'queued');END LOOP;
END $$;
CREATE OR REPLACE FUNCTION pitlane.order_delivery(target_id uuid,version uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE o pitlane.orders;v pitlane.receipt_versions;n integer;BEGIN SELECT * INTO o FROM pitlane.orders WHERE orders.id=target_id FOR UPDATE;SELECT * INTO v FROM pitlane.receipt_versions WHERE receipt_versions.id=version AND tenant_id=o.tenant_id AND project_id=o.project_id;IF NOT FOUND OR NOT EXISTS(SELECT FROM pitlane.artifacts WHERE artifacts.id=v.artifact_id AND state='published') THEN RAISE EXCEPTION 'MISSING_ARTIFACT';END IF;
IF o.state IN('settled','delivered_pending_capture','pending_reconciliation') THEN RETURN;END IF;
IF v.payload->>'finding' NOT IN('supported','contradicted') THEN INSERT INTO pitlane.payment_outbox(tenant_id,order_id,business_key,operation) VALUES(o.tenant_id,target_id,target_id::text||'/cancel','cancel') ON CONFLICT DO NOTHING;RETURN;END IF;
SELECT count(*) INTO n FROM pitlane.jobs j JOIN pitlane.receipt_versions rv ON rv.job_id=j.id WHERE j.order_id=target_id AND j.state='completed' AND rv.payload->>'finding' IN('supported','contradicted');
IF n<o.initial_units OR o.kind='pilot' AND o.summary_artifact_id IS NULL THEN RETURN;END IF;
UPDATE pitlane.orders SET state='delivered_pending_capture',delivered_version_id=version WHERE orders.id=target_id;
INSERT INTO pitlane.payment_outbox(tenant_id,order_id,business_key,operation,amount_cents) VALUES(o.tenant_id,target_id,target_id::text||'/capture','capture',o.amount_cents) ON CONFLICT DO NOTHING;
END $$;
CREATE OR REPLACE FUNCTION pitlane.collection_result(target_id uuid,state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE o pitlane.orders;journal uuid;mode text;hashes text[];BEGIN SELECT * INTO o FROM pitlane.orders WHERE orders.id=target_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND';END IF;IF o.state='settled' THEN RETURN;END IF;
IF state='settled' THEN IF o.state NOT IN('delivered_pending_capture','pending_reconciliation') OR o.delivered_version_id IS NULL THEN RAISE EXCEPTION 'CAPTURE_WITHOUT_DELIVERY';END IF;SELECT CASE WHEN runtime.mode='local' THEN 'fixture' ELSE billing_mode END INTO mode FROM pitlane.runtime;UPDATE pitlane.orders SET state='settled',settled_cents=amount_cents WHERE orders.id=target_id;INSERT INTO pitlane.journals(tenant_id,source_key,origin) VALUES(o.tenant_id,target_id::text||'/capture',mode) RETURNING journals.id INTO journal;INSERT INTO pitlane.journal_lines VALUES(journal,'processor_receivable','USD',2,o.amount_cents),(journal,'service_delivery','USD',2,-o.amount_cents);
IF o.kind='pilot' AND NOT o.retest_granted THEN SELECT array_agg(q.inputs_hash) INTO hashes FROM pitlane.jobs j JOIN pitlane.quotes q ON q.id=j.quote_id WHERE j.order_id=o.id;INSERT INTO pitlane.entitlement_lots(tenant_id,source_key,granted,ends_at,origin,scope_hashes) VALUES(o.tenant_id,'pilot/'||target_id::text||'/retest',5,now()+interval '30 days',CASE WHEN mode='live' THEN 'customer' ELSE 'internal' END,hashes) ON CONFLICT(source_key) DO NOTHING;UPDATE pitlane.orders SET retest_granted=true WHERE orders.id=target_id;END IF;
ELSIF state IN('pending_reconciliation','authorization_expired','collection_failed','cancelled') THEN UPDATE pitlane.orders SET state=collection_result.state WHERE orders.id=target_id;ELSE RAISE EXCEPTION 'INVALID_COLLECTION_STATE';END IF;END $$;
CREATE OR REPLACE FUNCTION pitlane.finish_billing_operation(target_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.payment_outbox SET completed_at=now(),lease_until=NULL WHERE payment_outbox.id=target_id $$;
CREATE OR REPLACE FUNCTION pitlane.retry_billing_operation(target_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.payment_outbox SET lease_until=NULL,available_at=now()+interval '30 seconds',last_error='PENDING_RECONCILIATION' WHERE payment_outbox.id=target_id $$;
CREATE OR REPLACE FUNCTION pitlane.pilot_summary(target_id uuid,artifact uuid,minutes integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE o pitlane.orders;version uuid;BEGIN IF NOT pitlane.is_operator(pitlane.actor_id()) OR minutes<1 OR minutes>45 THEN RAISE EXCEPTION 'OPERATOR_REVIEW_REQUIRED';END IF;SELECT * INTO o FROM pitlane.orders WHERE orders.id=target_id FOR UPDATE;IF NOT FOUND OR NOT pitlane.can_project(o.tenant_id,o.project_id,true) OR o.kind<>'pilot' OR NOT EXISTS(SELECT FROM pitlane.artifacts WHERE artifacts.id=artifact AND tenant_id=o.tenant_id AND project_id=o.project_id AND state='published' AND content_type='application/vnd.pitlane.pilot-summary+json') THEN RAISE EXCEPTION 'NOT_FOUND';END IF;UPDATE pitlane.orders SET summary_artifact_id=artifact,review_minutes=minutes WHERE orders.id=target_id;INSERT INTO pitlane.audit(tenant_id,actor_id,type,subject_id) VALUES(o.tenant_id,pitlane.actor_id(),'PILOT_HUMAN_REVIEW_DELIVERED',target_id);SELECT rv.id INTO version FROM pitlane.receipt_versions rv JOIN pitlane.jobs j ON j.id=rv.job_id WHERE j.order_id=target_id ORDER BY rv.issued_at DESC LIMIT 1;IF version IS NOT NULL THEN PERFORM pitlane.order_delivery(target_id,version);END IF;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.create_order(uuid,text,text,integer),pitlane.pilot_summary(uuid,uuid,integer),pitlane.is_operator(uuid) TO pitlane_web;
GRANT EXECUTE ON FUNCTION pitlane.billing_outbox(integer),pitlane.billing_order(uuid),pitlane.checkout_created(uuid,text,text),pitlane.order_authorized(uuid,text,timestamptz,bigint),pitlane.collection_result(uuid,text),pitlane.finish_billing_operation(uuid),pitlane.retry_billing_operation(uuid) TO pitlane_billing;
